from pathlib import Path

p = Path('project111-preview/app/src/main/java/com/offlineai/app/MainActivity.kt')
s = p.read_text()
needle = '''        restoreModel()\n    }\n\n    private fun registerDownloadReceiver()'''
hook = '''        restoreModel()\n        when {\n            intent.getBooleanExtra("__theme_menu_test", false) -> {\n                switchToConversation()\n                currentChatLines.clear()\n                currentChatLines += ChatLine("user", "BUILD111_TEMA_KORUMA_KULLANICI")\n                currentChatLines += ChatLine("assistant", "BUILD111_TEMA_KORUMA_ASISTAN")\n                renderCurrentChatLines()\n                input.setText("BUILD111_TASLAK_KORUNDU")\n            }\n            intent.getBooleanExtra("__typing_test", false) -> {\n                switchToConversation()\n                addUserBubble("BUILD111 kullanıcı yazı tipi testi")\n                root.postDelayed({\n                    conversationScroll.setOnScrollChangeListener { _, _, y, _, oldY -> android.util.Log.d("BUILD111_SCROLL", "old=$oldY y=$y") }\n                    val assistant = addAssistantMessage()\n                    assistant.thinking.stopAndHide()\n                    assistant.answer.visibility = View.VISIBLE\n                    val typing = TypingSession(this@MainActivity, assistant.answer) { scrollToBottom(force = false) }\n                    val started = SystemClock.uptimeMillis()\n                    launch {\n                        typing.append((1..20).joinToString(" ") { "Hızlı akış ${'$'}it: Yazı ChatGPT tarzı sans-serif görünmeli ve ekran aşağı doğru kararlı ilerlemelidir." })\n                        typing.complete()\n                        typing.awaitFinished()\n                        android.util.Log.d("BUILD111_TYPING", "DONE ms=${'$'}{SystemClock.uptimeMillis() - started} chars=${'$'}{assistant.answer.text.length}")\n                    }\n                }, 700L)\n            }\n        }\n    }\n\n    private fun registerDownloadReceiver()'''
if needle not in s:
    raise SystemExit('preview hook anchor missing')
p.write_text(s.replace(needle, hook, 1))
